import SwiftUI
struct CodexView: View { let snapshot: ProviderSnapshot; var body: some View { UsageView(snapshots:[snapshot]) } }
struct UsageView: View { let snapshots:[ProviderSnapshot]; var body: some View { ScrollView { VStack(alignment:.leading,spacing:12) { Text("Account usage").font(.title2.bold()); Text("Separate provider observations · no combined total").font(.subheadline).foregroundStyle(.secondary); LazyVGrid(columns:[GridItem(.adaptive(minimum:160),spacing:12)],spacing:12) { ForEach(snapshots,id:\.provider) { ProviderCard(snapshot:$0) } } }.padding(LifeOSTokens.pagePadding) }.background(LifeOSTokens.canvas).navigationTitle("Usage") } }
private struct ProviderCard: View { let snapshot:ProviderSnapshot; var body:some View { VStack(alignment:.leading,spacing:10) { HStack { Image(systemName:snapshot.provider == .codex ? "terminal" : "message"); Text(snapshot.provider.rawValue).font(.headline); Spacer(); Text(snapshot.provenance.quality == .observed ? "OFFICIAL" : snapshot.provenance.quality.rawValue.uppercased()).font(.caption2.bold()).foregroundStyle(snapshot.provenance.quality == .observed ? LifeOSTokens.success : LifeOSTokens.warning) }; Text(snapshot.accountLabel).font(.caption).foregroundStyle(.secondary); ForEach(snapshot.windows) { window in WindowRow(window:window) }; Text("Source: \(snapshot.provenance.source) · \(snapshot.provenance.freshness().rawValue)").font(.caption2).foregroundStyle(.secondary) }.padding(12).background(LifeOSTokens.surface,in:RoundedRectangle(cornerRadius:LifeOSTokens.corner)).overlay(RoundedRectangle(cornerRadius:LifeOSTokens.corner).stroke(LifeOSTokens.quietBorder)).accessibilityElement(children:.combine).accessibilityLabel("\(snapshot.provider.rawValue) account. \(snapshot.provenance.quality.rawValue) data. \(snapshot.windows.count) windows. Source \(snapshot.provenance.source). Freshness \(snapshot.provenance.freshness().rawValue)") } }
private struct WindowRow:View { let window:UsageWindow; var body:some View { VStack(alignment:.leading,spacing:4) { HStack { Text(window.label); Spacer(); if let p=window.usedPercent { Text(p,format:.percent) } else { Text("Unavailable").foregroundStyle(.secondary) } }; if let p=window.usedPercent { ProgressView(value:p).tint(LifeOSTokens.accent) } else { Text("Official window not supplied; no value invented").font(.caption2).foregroundStyle(.secondary) }; if let reset=window.resetAt { Text("Resets \(reset, style:.relative)").font(.caption2).foregroundStyle(.secondary) }; if let projection=window.projection { Text("Estimate · reset \(projection.percentAtReset,format:.percent) · exhaustion \(projection.percentAtExhaustion,format:.percent) · confidence \(projection.confidence,format:.percent) · \(projection.sampleSpan ?? "history")").font(.caption2).foregroundStyle(LifeOSTokens.warning) } }.accessibilityElement(children:.combine) } }
